package com.pandinila.broadband_management.entity;
import jakarta.persistence.*;
@Entity @Table(name="engineers") public class Engineer { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true) private String engineerId; private String name; private String email; private String specialization; private boolean available=true; @ManyToOne @JoinColumn(name="team_id") private SupportTeam team; public Long getId(){return id;} public String getEngineerId(){return engineerId;} public void setEngineerId(String v){engineerId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getSpecialization(){return specialization;} public void setSpecialization(String v){specialization=v;} public boolean isAvailable(){return available;} public void setAvailable(boolean v){available=v;} public SupportTeam getTeam(){return team;} public void setTeam(SupportTeam v){team=v;} }
